return {["fb23_01"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_01]],["name"]=[[角楼]],["permission"]=2,["rightUp"]=[[fb23_04]],["role1"]=[[fb23r01_1]],["role2"]=[[fb23r01_2]],["stepMusic"]=[[jiaobu]]},["fb23_02"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_02]],["name"]=[[角楼]],["permission"]=2,["role1"]=[[fb23r02_1]],["role2"]=[[fb23r02_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_07]]},["fb23_03"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_03]],["leftUp"]=[[fb23_11]],["name"]=[[角楼]],["permission"]=2,["role1"]=[[fb23r03_1]],["role2"]=[[fb23r03_2]],["stepMusic"]=[[jiaobu]]},["fb23_04"]={["dsc"]=[[这里是唐门的杂物间。屋内散乱的堆放着许多不知道是什么的东西。]],["id"]=[[fb23_04]],["item1"]=[[fb23item3]],["item2"]=[[fb23item25]],["item3"]=[[lylitem1]],["leftDown"]=[[fb23_01]],["name"]=[[杂物间]],["permission"]=2,["right"]=[[fb23_05]],["role1"]=[[fb23r04_1]],["stepMusic"]=[[jiaobu]]},["fb23_05"]={["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_05]],["left"]=[[fb23_04]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb23_06]],["stepMusic"]=[[jiaobu]]},["fb23_06"]={["dsc"]=[[这里是断木亭。堆放了许多粗大的树干，有几个唐门弟子居然在用手掌劈木柴，累得满头大汗。往北走就是厨房，有一阵阵饭菜的香气传来。]],["id"]=[[fb23_06]],["left"]=[[fb23_05]],["name"]=[[断木亭]],["permission"]=2,["right"]=[[fb23_07]],["role1"]=[[fb23r06_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_12]]},["fb23_07"]={["down"]=[[fb23_02]],["dsc"]=[[这里是挂剑堂。唐门是武林世家，当然有很多喜好收集兵器的人。剑是兵器之王，经过历代的收集，已经有不少神兵利器陈列在挂剑堂中。]],["id"]=[[fb23_07]],["item1"]=[[bfitem1]],["left"]=[[fb23_06]],["name"]=[[挂剑堂]],["permission"]=2,["right"]=[[fb23_08]],["role1"]=[[fb23r07_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_13]]},["fb23_08"]={["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_08]],["left"]=[[fb23_07]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb23_09]],["stepMusic"]=[[jiaobu]]},["fb23_09"]={["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_09]],["left"]=[[fb23_08]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb23_10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_14]]},["fb23_10"]={["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_10]],["left"]=[[fb23_09]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb23_11]],["stepMusic"]=[[jiaobu]]},["fb23_11"]={["dsc"]=[[“转朱阁，低倚户，照无眠”，这座阁楼正是取词中意境命名。阁中挂有不少灯笼，是唐门弟子晚上聚会，闲聊的好地方。]],["id"]=[[fb23_11]],["left"]=[[fb23_10]],["name"]=[[无眠阁]],["permission"]=2,["rightDown"]=[[fb23_03]],["role1"]=[[fb23r11_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_15]]},["fb23_12"]={["down"]=[[fb23_06]],["dsc"]=[[这里是唐门的厨房。阵阵川菜独特的香味扑鼻而来，口水都快流到下巴了。房中挂着串串辣椒，这是川菜最重要的调味品。]],["id"]=[[fb23_12]],["name"]=[[厨房]],["permission"]=2,["role1"]=[[fb23r12_1]],["stepMusic"]=[[jiaobu]]},["fb23_13"]={["down"]=[[fb23_07]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_13]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[fb23r13_1]],["role2"]=[[fb23r13_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_16]]},["fb23_14"]={["down"]=[[fb23_09]],["dsc"]=[[这里是唐门的练武场。放着些唐门的能工巧匠编制出的机关竹人，几个唐门弟子正在打竹人勤练武功。]],["fightBackground"]=[[擂台]],["id"]=[[fb23_14]],["name"]=[[练武场]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_17]]},["fb23_15"]={["down"]=[[fb23_11]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_15]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[fb23r15_1]],["role2"]=[[fb23r15_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_18]]},["fb23_16"]={["down"]=[[fb23_13]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_16]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[fb23r16_1]],["role2"]=[[fb23r16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_20]]},["fb23_17"]={["down"]=[[fb23_14]],["dsc"]=[[这是一间很大的休息室，陈设也很简单。靠墙放了十几张竹床。几个唐门弟子正和衣而卧，满屋子都是呼呼的打酣声。西边有张床是空的，你蹑手蹑脚地走了过去。]],["id"]=[[fb23_17]],["item1"]=[[fb23item9]],["item2"]=[[fb23item9]],["name"]=[[休息室]],["permission"]=2,["role1"]=[[fb23r17_1]],["role2"]=[[fb23r17_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_21]]},["fb23_18"]={["down"]=[[fb23_15]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_18]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[fb23r18_1]],["role2"]=[[fb23r18_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_23]]},["fb23_19"]={["dsc"]=[[这是一间独立的竹屋，掩映在一片梅花中。屋旁清泉淙淙，鸟语花香，环境极其幽雅。细看屋中各种物件，均为竹制，竹子经过特殊的处理，色泽淡黄，摸上去手感很舒适。]],["id"]=[[fb23_19]],["item1"]=[[fb23item22]],["name"]=[[千里居]],["permission"]=2,["right"]=[[fb23_20]],["role1"]=[[fb23r19_1]],["role2"]=[[fb23r19_5]],["stepMusic"]=[[jiaobu]]},["fb23_20"]={["down"]=[[fb23_16]],["dsc"]=[[这里是唐门供奉先人的大厅，厅内挂满了历代唐门先祖的画像。正中是一个很大的供桌，有一些果品、香烛。供桌顶上有一块匾。]],["id"]=[[fb23_20]],["left"]=[[fb23_19]],["name"]=[[祭祖厅]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_25]]},["fb23_21"]={["down"]=[[fb23_17]],["dsc"]=[[这是唐门中的一大片梅林，每逢满园梅花绽放，幽香袭人，令人觉得神清气爽。堪称唐门一大美景。]],["id"]=[[fb23_21]],["name"]=[[梅园]],["permission"]=2,["right"]=[[fb23_22]],["role1"]=[[fb23r21_1]],["stepMusic"]=[[jiaobu]]},["fb23_22"]={["dsc"]=[[这是唐门中的一大片梅林，每逢满园梅花绽放，幽香袭人，令人觉得神清气爽。堪称唐门一大美景。]],["id"]=[[fb23_22]],["left"]=[[fb23_21]],["name"]=[[梅园]],["permission"]=2,["right"]=[[fb23_23]],["stepMusic"]=[[jiaobu]]},["fb23_23"]={["down"]=[[fb23_18]],["dsc"]=[[这里是展梅阁，由于附近便是一大片梅圆，每每梅花吐蕊，朵朵绽放，淡淡幽香就飘至阁中，满屋生香，甚是惬意。]],["id"]=[[fb23_23]],["item1"]=[[zyitem1]],["left"]=[[fb23_22]],["name"]=[[展梅阁]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_26]]},["fb23_24"]={["dsc"]=[[这里是藕香湖的南端，楼分三层，如果上得第三层，便可总整个藕香湖的美景。进得魁星楼，迎面便是左手书，右手笔，神情威猛的魁星。往上是红木扶梯，可以到第二层。]],["id"]=[[fb23_24]],["item1"]=[[fb23item16]],["item2"]=[[fb23item22]],["item3"]=[[fb23item23]],["item4"]=[[fb23item24]],["name"]=[[魁星阁]],["permission"]=2,["role1"]=[[fb23r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_27]]},["fb23_25"]={["down"]=[[fb23_20]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_25]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_28]]},["fb23_26"]={["down"]=[[fb23_23]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_26]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_29]]},["fb23_27"]={["down"]=[[fb23_24]],["dsc"]=[[弯弯曲曲的回廊，廊下就是藕香湖水，湖面满是翠绿的荷叶，中间点缀着朵朵粉色荷花，偶尔可以看到几条鱼儿在荷间游弋。]],["id"]=[[fb23_27]],["leftUp"]=[[fb23_32]],["name"]=[[曲廊]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb23_28"]={["down"]=[[fb23_25]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_28]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_35]]},["fb23_29"]={["down"]=[[fb23_26]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_29]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_38]]},["fb23_30"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_30]],["name"]=[[角楼]],["permission"]=2,["right"]=[[fb23_31]],["role1"]=[[fb23r30_1]],["role2"]=[[fb23r30_2]],["role3"]=[[fb23r30_3]],["stepMusic"]=[[jiaobu]]},["fb23_31"]={["dsc"]=[[弯弯曲曲的回廊，廊下就是藕香湖水，湖面满是翠绿的荷叶，中间点缀着朵朵粉色荷花，偶尔可以看到几条鱼儿在荷间游弋。]],["id"]=[[fb23_31]],["left"]=[[fb23_30]],["name"]=[[曲廊]],["permission"]=2,["right"]=[[fb23_32]],["role1"]=[[fb23r31_1]],["role2"]=[[fb23r31_2]],["stepMusic"]=[[jiaobu]]},["fb23_32"]={["dsc"]=[[这是藕香湖中一间雅致的小榭，四面皆有雕花小窗，窗上挂有暗花丝帘。中间有一琴台，台上有焦尾古琴，青铜小鼎中正焚着檀香。一抹憔悴的身影，纤纤玉指拨弄着琴弦。]],["id"]=[[fb23_32]],["left"]=[[fb23_31]],["name"]=[[藕香小榭]],["permission"]=2,["right"]=[[fb23_33]],["rightDown"]=[[fb23_27]],["role1"]=[[fb23r32_1]],["role2"]=[[fb23r32_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_40]]},["fb23_33"]={["dsc"]=[[弯弯曲曲的回廊，廊下就是藕香湖水，湖面满是翠绿的荷叶，中间点缀着朵朵粉色荷花，偶尔可以看到几条鱼儿在荷间游弋。]],["id"]=[[fb23_33]],["left"]=[[fb23_32]],["name"]=[[曲廊]],["permission"]=2,["right"]=[[fb23_34]],["role1"]=[[fb23r33_1]],["role2"]=[[fb23r33_2]],["stepMusic"]=[[jiaobu]]},["fb23_34"]={["dsc"]=[[精益堂是唐门弟子武功到了一定境界之后，精进勤修的地方。精益堂主唐亮是唐门第一高手，江湖号称“千手千眼”，暗器功夫已入化境。]],["id"]=[[fb23_34]],["left"]=[[fb23_33]],["name"]=[[精益堂]],["permission"]=2,["right"]=[[fb23_35]],["role1"]=[[fb23r34_1]],["stepMusic"]=[[jiaobu]]},["fb23_35"]={["down"]=[[fb23_28]],["dsc"]=[[这里是唐门的议事大厅。整个大厅建筑得很奇怪，四周有八根朱红大柱地面黝黑发亮，是唐门平时冶炼暗器所剩的铁屑溶制成的整块。正中是一个很大的八卦图。]],["id"]=[[fb23_35]],["left"]=[[fb23_34]],["name"]=[[议事大厅]],["permission"]=2,["right"]=[[fb23_36]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_41]]},["fb23_36"]={["dsc"]=[[这里是唐门的刑堂。刑堂堂主唐无情是江湖上有名的煞星，对于折磨人更是有独到的心得，如果落在他手上，必定是生不如死。]],["id"]=[[fb23_36]],["left"]=[[fb23_35]],["name"]=[[刑堂]],["permission"]=2,["right"]=[[fb23_37]],["role1"]=[[fb23r36_1]],["stepMusic"]=[[jiaobu]]},["fb23_37"]={["dsc"]=[[这里是唐门的兵器库，里面整整齐齐堆放着各种各样的暗器及刀剑，唐门弟子可以在这儿取用。库里还有火炉和铁锤，可以自己升火打造钢镖。]],["id"]=[[fb23_37]],["left"]=[[fb23_36]],["name"]=[[兵器库]],["permission"]=2,["right"]=[[fb23_38]],["role1"]=[[sbitem32]],["stepMusic"]=[[jiaobu]]},["fb23_38"]={["down"]=[[fb23_29]],["dsc"]=[[潇潇暮雨楼虽然称作楼，但是却只有一层。楼中有螺旋状悬梯延四周盘旋而上，足足有十几丈高，登上最高处，甚至可以看见远处烟雨朦胧的长江江面。正是“潇潇暮雨洒江天”的美景。]],["id"]=[[fb23_38]],["item1"]=[[fb23item12]],["left"]=[[fb23_37]],["name"]=[[潇潇暮雨楼]],["permission"]=2,["right"]=[[fb23_39]],["role1"]=[[fb23r38_1]],["role2"]=[[fb23r38_2]],["role3"]=[[fb23r38_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_42]]},["fb23_39"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_39]],["left"]=[[fb23_38]],["name"]=[[角楼]],["permission"]=2,["role1"]=[[fb23r39_1]],["role2"]=[[fb23r39_2]],["stepMusic"]=[[jiaobu]]},["fb23_40"]={["down"]=[[fb23_32]],["dsc"]=[[这是一座高大的牌坊，全部由大理石砌成，顶部几个苍劲有力的大字“藕香湖”。两边是云边儿和雕花。往南就是唐家堡内的藕香湖，随风阵阵飘来淡淡荷香。]],["id"]=[[fb23_40]],["name"]=[[藕香湖牌坊]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb23_41"]={["down"]=[[fb23_35]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_41]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_44]]},["fb23_42"]={["down"]=[[fb23_38]],["dsc"]=[[这是一座八角亭，亭内四面有大理石园桌和条凳，供人休息。]],["id"]=[[fb23_42]],["name"]=[[天星亭]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb23_43"]={["dsc"]=[[一汪黑色的池水，还没走进就闻到一股浓浓的墨香。看来是有人常常在此清洗笔砚，日积月累，整池的碧水就变成了一池墨水。]],["id"]=[[fb23_43]],["name"]=[[墨池]],["permission"]=1,["role1"]=[[fb23r43_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_45]]},["fb23_44"]={["down"]=[[fb23_41]],["dsc"]=[[这里是心意堂。堂前最明显的就是一幅气势逼人的猛虎下山图，据说是当年江南四大才子之一唐寅所赠。]],["id"]=[[fb23_44]],["name"]=[[心意堂]],["permission"]=2,["role1"]=[[fb23r44_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_46]]},["fb23_45"]={["down"]=[[fb23_43]],["dsc"]=[[这是花园中一座雅致的阁楼。唐门中颇多喜好舞文弄墨的弟子，常常聚在丹青阁中交流书法、画技。阁中挂着许多画卷、书法作品。往南走是一汪池水。]],["id"]=[[fb23_45]],["name"]=[[丹青阁]],["permission"]=1,["role1"]=[[fb23r45_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_49]]},["fb23_46"]={["down"]=[[fb23_44]],["dsc"]=[[这里是天井，一大片开阔的空旷地，有几个练功用的竹人。往北走是留剑堂，往南是心意堂。]],["id"]=[[fb23_46]],["name"]=[[天井]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_50]]},["fb23_47"]={["dsc"]=[[这是唐门待客的茶室。室内摆设很雅致，有几张精致的檀香木桌，以及几把竹椅四面是檀香雕花窗，可以望见窗外的花园。]],["id"]=[[fb23_47]],["item1"]=[[fb23item10]],["name"]=[[茶室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_53]]},["fb23_48"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_48]],["name"]=[[角楼]],["permission"]=2,["right"]=[[fb23_49]],["role1"]=[[fb23r48_1]],["role2"]=[[fb23r48_2]],["stepMusic"]=[[jiaobu]]},["fb23_49"]={["down"]=[[fb23_45]],["dsc"]=[[这是一大片花园。唐门地处蜀南，占地广阔，气候适宜花草生长。加上唐门弟练功之余，皆喜欢侍弄花草，所以整个花园品种繁多，终年花团锦簇，非常漂亮。]],["id"]=[[fb23_49]],["item1"]=[[fb23item7]],["item2"]=[[fb23item11]],["item3"]=[[fb23item11]],["left"]=[[fb23_48]],["name"]=[[花园]],["permission"]=1,["right"]=[[fb23_50]],["role1"]=[[fb23r49_1]],["stepMusic"]=[[jiaobu]]},["fb23_50"]={["down"]=[[fb23_46]],["dsc"]=[[“留剑堂”，顾名思义，凡是来唐门的访客，过这儿都要解下兵器，否则不允许再深入唐门。]],["id"]=[[fb23_50]],["left"]=[[fb23_49]],["name"]=[[留剑堂]],["permission"]=1,["right"]=[[fb23_51]],["role1"]=[[fb23r50_1]],["role2"]=[[fb23r50_2]],["role3"]=[[fb23r50_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_55]]},["fb23_51"]={["dsc"]=[[这是一大片花园。唐门地处蜀南，占地广阔，气候适宜花草生长。加上唐门弟练功之余，皆喜欢侍弄花草，所以整个花园品种繁多，终年花团锦簇，非常漂亮。]],["id"]=[[fb23_51]],["item1"]=[[fb23item11]],["item2"]=[[fb23item11]],["left"]=[[fb23_50]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb23_52]],["role1"]=[[fb23r49_100]],["role2"]=[[fb23r49_101]],["stepMusic"]=[[jiaobu]]},["fb23_52"]={["dsc"]=[[这里是唐门供访客住宿休息的地方。处在花园之中，推窗往外望，便能看见满园鲜花灿烂，闻到阵阵幽香，甚是心旷神怡。]],["id"]=[[fb23_52]],["left"]=[[fb23_51]],["name"]=[[客房]],["permission"]=2,["right"]=[[fb23_53]],["stepMusic"]=[[jiaobu]]},["fb23_53"]={["down"]=[[fb23_47]],["dsc"]=[[这是一大片花园。唐门地处蜀南，占地广阔，气候适宜花草生长。加上唐门弟练功之余，皆喜欢侍弄花草，所以整个花园品种繁多，终年花团锦簇，非常漂亮。]],["id"]=[[fb23_53]],["left"]=[[fb23_52]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb23_54]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb23_54"]={["dsc"]=[[这是唐家堡的角楼。唐门虽声名显赫，势力庞大，但是也树敌不少。为防外敌突袭，所以四周都有这样的角楼。有一队武士在这儿巡逻。]],["id"]=[[fb23_54]],["left"]=[[fb23_53]],["name"]=[[角楼]],["permission"]=2,["role1"]=[[fb23r54_100]],["role2"]=[[fb23r54_101]],["stepMusic"]=[[jiaobu]]},["fb23_55"]={["down"]=[[fb23_50]],["dsc"]=[[这是一面宽阔的照壁，上面雕有瑞兽麒麟，活灵活现，仿佛要破壁而出。两旁各有一通道。绕过照壁，就可以进入“留剑堂”。]],["id"]=[[fb23_55]],["name"]=[[照壁]],["permission"]=1,["role1"]=[[fb23r55_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_56]]},["fb23_56"]={["down"]=[[fb23_55]],["dsc"]=[[下了画舫，抬头一望，赫然见到“唐家堡”三个大字。你已经来到了神秘而声名显赫声名显赫的唐门。大门口是两个威武雄壮的铜狮，两旁是笔力遒劲的对联。]],["id"]=[[fb23_56]],["name"]=[[唐家堡大门]],["permission"]=1,["role1"]=[[fb23r56_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_58]]},["fb23_57"]={["down"]=[[fb23_87]],["dsc"]=[[这一段竹林全部是高大的楠竹，青石路两旁的竹子遮天闭日，只是偶尔有点点光亮泄在路上，青青的竹林裹着小路，犹如翡翠做的一般，所以这儿叫做“翡翠长廊”。]],["id"]=[[fb23_57]],["leftUp"]=[[fb23_59]],["name"]=[[翡翠长廊]],["permission"]=1,["right"]=[[fb23_58]],["role1"]=[[sbitem6]],["stepMusic"]=[[jiaobu]]},["fb23_58"]={["down"]=[[fb23_56]],["dsc"]=[[出了竹林，面前是一片平静的湖面，微风拂过，水面泛起鳞鳞波纹。远远望去，湖中水雾蒙蒙，隐约有一个小岛的影子。水域很宽望不到对岸。]],["id"]=[[fb23_58]],["item1"]=[[2019qxhdd1]],["left"]=[[fb23_57]],["name"]=[[扶风湖]],["permission"]=1,["right"]=[[fb23_72]],["role1"]=[[bfr58_1]],["stepMusic"]=[[jiaobu]]},["fb23_59"]={["dsc"]=[[这是一片郁郁葱葱的竹林，这片竹林中竹子种类繁多，有状若罗汉肚的罗汉竹，有隐隐红点的湘妃竹，有笔直粗壮的楠竹..竹叶的清香，令人心旷神怡。]],["fightBackground"]=[[森林外]],["id"]=[[fb23_59]],["name"]=[[竹林]],["permission"]=1,["rightDown"]=[[fb23_57]],["role1"]=[[sbitem4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_60]]},["fb23_60"]={["down"]=[[fb23_59]],["dsc"]=[[这是路旁一个简陋的茶铺，周围满是竹林环绕，环境倒是清幽，简单的几张竹桌、竹椅，时不时有人坐着歇歇脚，喝两口茉莉花茶。南边有一道竹门虚掩着。]],["fightBackground"]=[[山内]],["id"]=[[fb23_60]],["item1"]=[[fb23item6]],["item2"]=[[fb23item100]],["item3"]=[[sbitem2]],["name"]=[[茶铺]],["permission"]=1,["role1"]=[[fb23r60_1]],["role2"]=[[fb23r60_2]],["role3"]=[[fb23r60_3a]],["role4"]=[[bfr60_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_61]]},["fb23_61"]={["down"]=[[fb23_60]],["dsc"]=[[自古蜀道路难行，一代诗仙李白诗曰:蜀道之难难于上青天！天梯石栈犬错勾连，猿鸟哀号古木遮天，岩峦九折青泥盘盘。因此这条路又叫登天道，世人难行。]],["fightBackground"]=[[山内]],["id"]=[[fb23_61]],["name"]=[[蜀道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb23_62"]={["down"]=[[fb23_66]],["dsc"]=[[这里是唐门机关的总机关室，所有的机关都可以在这里启动关闭。房内全是机簧与转轴，其材质或铁或木或石，精密无比，令人叹为观止。都在缓慢转动，地下传来隆隆震动之声。]],["id"]=[[fb23_62]],["name"]=[[机关房]],["permission"]=2,["right"]=[[fb23_63]],["role1"]=[[sbitem12]],["stepMusic"]=[[jiaobu]]},["fb23_63"]={["down"]=[[fb23_69]],["dsc"]=[[唐门禁地之中设置的箭楼。这箭楼仿照城楼设计，全部由青石建成，高约四丈，楼上四面开阔，四面都设置着机关重弩，靠近的不速之客霎时便会被射成刺猬。]],["id"]=[[fb23_63]],["left"]=[[fb23_62]],["name"]=[[箭楼]],["permission"]=2,["right"]=[[fb23_64]],["role1"]=[[sbitem13]],["stepMusic"]=[[jiaobu]]},["fb23_64"]={["dsc"]=[[唐门禁地被一条河流截为两半，连接两地的便是十二根手腕粗细的铁索。唐门中人重修轻功，行走其上自然如履平地，若是常人，便会因为猛烈的河风晃动得难以站立其上。]],["id"]=[[fb23_64]],["left"]=[[fb23_63]],["name"]=[[铁索桥]],["permission"]=2,["right"]=[[fb23_65]],["stepMusic"]=[[jiaobu]]},["fb23_65"]={["down"]=[[fb23_68]],["dsc"]=[[唐门禁地之中设置的箭楼。这箭楼仿照城楼设计，全部由青石建成，高约四丈，楼上四面开阔，四面都设置着机关重弩，靠近的不速之客霎时便会被射成刺猬。]],["id"]=[[fb23_65]],["left"]=[[fb23_64]],["name"]=[[箭楼]],["permission"]=2,["role1"]=[[sbitem14]],["stepMusic"]=[[jiaobu]]},["fb23_66"]={["down"]=[[fb23_70]],["dsc"]=[[一条青石板铺成的小道。小道两旁每隔数丈便有一盏石灯。这条小道虽然看起来寻常，但四周都隐藏着机关，只要机关开启，便能须臾之间取人性命。]],["id"]=[[fb23_66]],["name"]=[[机关道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_62]]},["fb23_67"]={["dsc"]=[[修文阁的二层阁楼。里面放着一张床，窗边放着一张桌台，桌台上有些书信。房间内弥漫着淡淡的药味。]],["id"]=[[fb23_67]],["item1"]=[[sbr67_5]],["item2"]=[[sbitem17]],["name"]=[[阁楼二层]],["permission"]=2,["right"]=[[fb23_68]],["role1"]=[[sbr67_1]],["role2"]=[[sbr67_2]],["role3"]=[[sbr67_3]],["role4"]=[[sbr67_4]],["stepMusic"]=[[jiaobu]]},["fb23_68"]={["down"]=[[fb23_71]],["dsc"]=[[一座外形精巧的六角小阁楼。屋檐挂着铜铃，随风发出清脆声响。屋内陈设简朴，挂着几幅字画，正中间的八仙桌上放着还未饮用完的茶水。]],["id"]=[[fb23_68]],["left"]=[[fb23_67]],["name"]=[[修文阁]],["permission"]=2,["role1"]=[[sbitem1]],["role2"]=[[sbitem8]],["role3"]=[[sbitem18]],["role4"]=[[sbitem31]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_65]]},["fb23_69"]={["down"]=[[fb23_75]],["dsc"]=[[唐门禁地被一条河流截为两半，连接两地的便是十二根手腕粗细的铁索。唐门中人重修轻功，行走其上自然如履平地，若是常人，便会因为猛烈的河风晃动得难以站立其上。]],["id"]=[[fb23_69]],["name"]=[[铁索桥]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_63]]},["fb23_70"]={["down"]=[[fb23_74]],["dsc"]=[[一条碎石铺成的小道。两旁草地被修剪得十分整齐。]],["id"]=[[fb23_70]],["name"]=[[碎石道]],["permission"]=2,["role1"]=[[sbitem15]],["role2"]=[[sbitem16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_66]]},["fb23_71"]={["down"]=[[fb23_77]],["dsc"]=[[这里是机关林立的地带，为禁地防止闯入者而设置。机关林树立着大大小小的铁柱，铁柱中藏着各式各样的机关，人若想通过必须穿过铁柱，若不知道安全之路便会命丧当场。]],["id"]=[[fb23_71]],["name"]=[[机关林]],["permission"]=2,["role1"]=[[sbitem19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_68]]},["fb23_72"]={["dsc"]=[[扶风湖的沿岸，生长着不少芦苇，偶尔会有白鹭贴着湖面飞过。此处连通着唐家堡与唐门禁地，但唐门禁地平日不允许唐门弟子进入，因而显得人迹罕至。]],["id"]=[[fb23_72]],["left"]=[[fb23_58]],["name"]=[[湖岸]],["permission"]=2,["right"]=[[fb23_73]],["stepMusic"]=[[jiaobu]]},["fb23_73"]={["dsc"]=[[唐门禁地前的对开青石巨门。平时都是紧锁着。其上有小小凹槽，只需将唐门密令放入其中，机关便会牵动石门开启。门上是一块门匾，上银字草书“唐门禁地”四字。门口站着唐门禁地的守卫。]],["id"]=[[fb23_73]],["left"]=[[fb23_72]],["name"]=[[禁地石门]],["permission"]=2,["right"]=[[fb23_74]],["role1"]=[[sbr73_1]],["role2"]=[[sbitem9]],["stepMusic"]=[[jiaobu]]},["fb23_74"]={["down"]=[[fb23_78]],["dsc"]=[[一条碎石铺成的小道。两旁草地被修剪得十分整齐。]],["id"]=[[fb23_74]],["left"]=[[fb23_73]],["name"]=[[碎石道]],["permission"]=2,["right"]=[[fb23_75]],["role1"]=[[sbr74_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_70]]},["fb23_75"]={["down"]=[[fb23_80]],["dsc"]=[[此处是一处接壤河岸的高台，登上高台便可以将对岸风景尽收眼底。封剑台为唐门上任家主唐阡陌所建造，台上设封剑碑，碑下埋藏着唐门铸造兵器的技艺书。唐阡陌当年因为铸剑好胜而害人一家惨死，回到唐门之后便封存了铸造术，不再允许唐门铸造。]],["id"]=[[fb23_75]],["left"]=[[fb23_74]],["name"]=[[封剑台]],["permission"]=2,["role1"]=[[sbitem20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_69]]},["fb23_76"]={["dsc"]=[[唐门引河水修建成的池子。池水大约及膝，里面全是唐门废弃不用的武器，插满了整个不算小的池子。因为唐门武器原本都为本门所造，铸造技艺特殊，为了不外传，才会将废弃的武器扔于此处。]],["id"]=[[fb23_76]],["name"]=[[弃剑池]],["permission"]=2,["right"]=[[fb23_77]],["stepMusic"]=[[jiaobu]]},["fb23_77"]={["down"]=[[fb23_79]],["dsc"]=[[此处是唐门重地，非唐门宗系门人不得进入其中。藏书楼中放着唐门世世代代武功绝学、机关术等各种不外传的书籍，有人日夜把守。]],["id"]=[[fb23_77]],["left"]=[[fb23_76]],["name"]=[[藏书楼]],["permission"]=2,["role1"]=[[sbitem21]],["role2"]=[[sbitem22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_71]]},["fb23_78"]={["down"]=[[fb23_81]],["dsc"]=[[一条青石板铺成的小道。小道两旁每隔数丈便有一盏石灯。这条小道虽然看起来寻常，但四周都隐藏着机关，只要机关开启，便能须臾之间取人性命。]],["id"]=[[fb23_78]],["name"]=[[机关道]],["permission"]=2,["role1"]=[[sbitem23]],["role2"]=[[sbitem24]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_74]]},["fb23_79"]={["down"]=[[fb23_82]],["dsc"]=[[这里是机关林立的地带，为禁地防止闯入者而设置。机关林树立着大大小小的铁柱，铁柱中藏着各式各样的机关，人若想通过必须穿过铁柱，若不知道安全之路便会命丧当场。]],["id"]=[[fb23_79]],["name"]=[[机关林]],["permission"]=2,["role1"]=[[sbitem25]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_77]]},["fb23_80"]={["down"]=[[fb23_84]],["dsc"]=[[唐门禁地被一条河流截为两半，连接两地的便是十二根手腕粗细的铁索。唐门中人重修轻功，行走其上自然如履平地，若是常人，便会因为猛烈的河风晃动得难以站立其上。]],["id"]=[[fb23_80]],["name"]=[[铁索桥]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_75]]},["fb23_81"]={["down"]=[[fb23_83]],["dsc"]=[[一条青石板铺成的小道。小道两旁每隔数丈便有一盏石灯。这条小道虽然看起来寻常，但四周都隐藏着机关，只要机关开启，便能须臾之间取人性命。]],["id"]=[[fb23_81]],["name"]=[[机关道]],["permission"]=2,["role1"]=[[sbitem26]],["role2"]=[[sbitem27]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_78]]},["fb23_82"]={["down"]=[[fb23_86]],["dsc"]=[[这里是唐门禁地中机关师们修炼武艺的地方。阁楼中十分宽敞，四周放着武器架，上面放着各种奇形怪状的兵器。]],["id"]=[[fb23_82]],["name"]=[[习武阁]],["permission"]=2,["role1"]=[[sbitem28]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_79]]},["fb23_83"]={["dsc"]=[[这里是唐门机关的总机关室，所有的机关都可以在这里启动关闭。房内全是机簧与转轴，其材质或铁或木或石，精密无比，令人叹为观止。都在缓慢转动，地下传来隆隆震动之声。]],["id"]=[[fb23_83]],["name"]=[[机关房]],["permission"]=2,["right"]=[[fb23_84]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_81]]},["fb23_84"]={["dsc"]=[[唐门禁地之中设置的箭楼。这箭楼仿照城楼设计，全部由青石建成，高约四丈，楼上四面开阔，四面都设置着机关重弩，靠近的不速之客霎时便会被射成刺猬。]],["id"]=[[fb23_84]],["left"]=[[fb23_83]],["name"]=[[箭楼]],["permission"]=2,["right"]=[[fb23_85]],["role1"]=[[sbitem29]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_80]]},["fb23_85"]={["dsc"]=[[唐门禁地被一条河流截为两半，连接两地的便是十二根手腕粗细的铁索。唐门中人重修轻功，行走其上自然如履平地，若是常人，便会因为猛烈的河风晃动得难以站立其上。]],["id"]=[[fb23_85]],["left"]=[[fb23_84]],["name"]=[[铁索桥]],["permission"]=2,["right"]=[[fb23_86]],["stepMusic"]=[[jiaobu]]},["fb23_86"]={["dsc"]=[[唐门禁地之中设置的箭楼。这箭楼仿照城楼设计，全部由青石建成，高约四丈，楼上四面开阔，四面都设置着机关重弩，靠近的不速之客霎时便会被射成刺猬。]],["id"]=[[fb23_86]],["left"]=[[fb23_85]],["name"]=[[箭楼]],["permission"]=2,["role1"]=[[sbitem30]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_82]]},["fb23_87"]={["down"]=[[fb23_88]],["dsc"]=[[这里一段长廊，两旁是红木廊柱，顶上有很漂亮的漆画和书法。每一段长廊的书画恰好都组成了一个故事或是一个久远的传说。]],["id"]=[[fb23_87]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[fb23_34a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb23_57]]},["fb23_88"]={["dsc"]=[[笔直青翠的竹子，风起，竹叶簌簌作响。]],["id"]=[[fb23_88]],["item1"]=[[fubentiaozhuan1]],["name"]=[[唐家竹林]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb23_87]]}}000000000000